<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; class SkillLogbookRequirement extends Model { protected $fillable=['course_id','department_id','skill_code','name_ar','name_en','required_proficiency','minimum_count','requires_supervisor_signature','notes','archived_at']; protected function casts():array{return ['minimum_count'=>'integer','requires_supervisor_signature'=>'boolean'];} public function course():BelongsTo{return $this->belongsTo(Course::class);} public function department():BelongsTo{return $this->belongsTo(Department::class);} }
